<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT p.*,MIN(pp.price) min_price,MAX(pp.price) max_price FROM products p LEFT JOIN product_prices pp ON pp.product_id=p.id GROUP BY p.id ORDER BY p.sort_order,p.id DESC')->fetchAll();$title='Products';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row sm:items-end justify-between gap-3"><div><h1 class="page-title">Products</h1><p class="page-sub">Kelola layanan, harga level, provider, CEIR dan WhatsApp.</p></div><div class="flex flex-wrap gap-2"><button class="btn" id="sync-btn"><i data-lucide="refresh-cw"></i>Sync CeirGo</button><a class="btn btn-dark" href="/admin/products/new"><i data-lucide="plus"></i>Add product</a></div></div><?php if(isset($_GET['created'])):?><div class="saas-card p-4 mt-5 text-sm font-semibold">✓ Produk berhasil ditambahkan.</div><?php endif?><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[850px]"><thead><tr><th>Product</th><th>Code</th><th>Price</th><th>Provider</th><th>CEIR</th><th>WA Group</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $p):?><tr class="border-t" style="border-color:var(--line)"><td><b><?=htmlspecialchars($p['name'])?></b><div class="text-xs text-zinc-500"><?=htmlspecialchars($p['processing_time']??'')?></div></td><td><code><?=htmlspecialchars($p['code'])?></code></td><td>Rp<?=number_format((float)($p['min_price']??0),0,',','.')?><?php if(($p['max_price']??0)!==($p['min_price']??0)):?> – Rp<?=number_format((float)$p['max_price'],0,',','.')?><?php endif?></td><td><span class="badge"><?=htmlspecialchars($p['provider_type'])?></span></td><td><?=$p['ceir_check_enabled']?'ON':'OFF'?></td><td class="max-w-40 truncate"><?=htmlspecialchars($p['whatsapp_group_id']??'-')?></td><td><span class="badge"><?=$p['is_active']?'ACTIVE':'OFF'?></span></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="p-10 text-center text-zinc-500">Belum ada produk. Klik Add product untuk membuat layanan pertama.</div><?php endif?></div><script>document.getElementById('sync-btn').addEventListener('click',async function(){this.disabled=true;try{const r=await fetch('/api/admin/products/import-ceirgo',{method:'POST',headers:{'Accept':'application/json','X-CSRF-Token':'<?=App::csrf()?>'}});const j=await r.json();Swal.fire(j.ok?'Sync selesai':'Sync gagal',j.message||((j.imported||0)+' service tersinkron'),j.ok?'success':'error')}catch(e){Swal.fire('Sync gagal',e.message,'error')}finally{this.disabled=false}})</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>